struct Flash {unsigned command=0,remaining=0,writes=0;void write(uint8_t*memory,uint32_t a,uint8_t v){auto offset=a-0x200000;if(command==3){if(remaining!=1)memory[a]=v;++writes;if(!--remaining)command=0;return;}if(command==0&&offset==0x5555&&v==0xaa)command=1;else if(command==1&&offset==0x2aaa&&v==0x55)command=2;else if(command==2&&offset==0x5555&&v==0xa0){command=3;remaining=256;}else command=0;}};
struct RBus:H8SDevice{Ref&c;Flash flash{};std::array<Event,32>e{};unsigned n=0;explicit RBus(Ref&v):c(v){}uint8_t read(uint32_t a)override{auto v=a>=0xfffd20&&a<0xfffd24?uint8_t((c.cycles/1000)>>((0xfffd23-a)*8)):c.memory[a];if(observed(a))e[n++]={c.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(observed(a))e[n++]={c.cycles,a,v,true};if(a>=0x200000&&a<0x240000)flash.write(c.memory,a,v);else c.memory[a]=v;}};
struct NBus:kstation::ControllerResourceBus{Flash flash{};std::array<Event,32>e{};unsigned n=0;bool enabled=false;bool mapped(uint32_t a)const override{return observed(a);}uint8_t read(uint32_t a)override{auto v=a>=0xfffd20&&a<0xfffd24?uint8_t((state_->cycles/1000)>>((0xfffd23-a)*8)):state_->memory[a];if(enabled)e[n++]={state_->cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(enabled)e[n++]={state_->cycles,a,v,true};if(a>=0x200000&&a<0x240000)flash.write(state_->memory,a,v);else state_->memory[a]=v;}};
int main(int argc,char**argv){if(argc!=2)return 77;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};if(rom.size()!=49728)return 1;auto c=std::make_unique<Ref>();auto d=std::make_unique<kstation::ControllerDeviceState>();c->loadmem(rom.data(),unsigned(rom.size()),0);d->loadMemory(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0x400000);RBus x(*c);NBus y;c->memmap(&x,0xba00,0x1600);c->memmap(&x,0x130,5);c->memmap(&x,0x200000,0x40000);c->memmap(&x,0xfffe32,2);c->memmap(&x,0xfffd20,4);d->attachBus(&y);kstation::ControllerInterruptRuntime irq;kstation::ControllerMidiSysExRuntime rt;if(!irq.bindVerifiedFirmware(*d,rom.data(),rom.size())||!rt.bindVerifiedFirmware(*d,rom.data(),rom.size()))return 2;y.enabled=true;for(uint32_t a:{0x165eu,0x571eu,0x816cu,0x7644u,0x239eu,0x237eu,0x12b6u,0x20e2u,0x3256u,0x3306u,0x332cu,0x334au}){c->memory[a]=0x54;c->memory[a+1]=0x70;}uint64_t graphs=0,phases=0,events=0,shorts=0,services=0,timeouts=0;for(unsigned flags:{0u,128u})for(uint8_t mode:{uint8_t(3)})for(uint8_t type:{uint8_t(3)})for(uint8_t count:{uint8_t(0)}){rt.reset();irq.reset();irq.setMask(flags&128?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled);auto put=[&](uint32_t a,uint8_t v){c->memory[a]=d->memory[a]=v;};auto word=[&](uint32_t a,uint16_t v){put(a,v>>8);put(a+1,v);};auto wide=[&](uint32_t a,uint32_t v){word(a,v>>16);word(a+2,v);};put(0xcad3,mode==1&&count==5?uint8_t(flags&4?0x7f:flags&8?3:4):type);put(0xcd0e,mode);put(0xcd0f,rom[0x134]);put(0xcd10,type);put(0xcd11,1);put(0xcd12,flags&1?8:9);put(0xcd13,flags&1?7:8);put(0xcd14,1);put(0xcd15,2);put(0xbb16,3);put(0xbb14,3);put(0x21ffff,0x5a);for(unsigned i=0;i<4;++i)put(0xcc0c+i,rom[0x130+i]);if(mode==1&&count==5&&(flags&16))put(0xcc0c,uint8_t(rom[0x130]^1));put(0xcc10,mode==1&&count==5?uint8_t(flags&2?0x40:rom[0x134]):type);put(0xcc11,0x7f);word(0xcc0a,count);wide(0xcc06,0xcc0c+count);word(0xcd0c,count+1);c->pc=c->makepc(0x2f68);c->setSP(0xffff10);for(unsigned i=0;i<4;++i)c->memory[0xffff10+i]=uint8_t(0x7000u>>(8*(3-i)));c->reg32(4)=0xcad3;c->ccr=uint8_t(flags);c->pending_irqs=d->pendingIrqs=0;c->pending_irqs_high=d->pendingIrqsHigh=0;c->interruptMode2=d->interruptMode2=false;c->cycles=d->cycles=250000;c->history(-1,-1);d->lastRead=d->lastWrite=-1;if(!rt.start(kstation::ControllerMidiSysExRuntime::Kind::Start,0xcad3))return 3;for(unsigned k=0;rt.active();++k){if(k>100000){std::fprintf(stderr,"hang pc=%x mode=%u type=%u\n",c->getPC(),mode,type);return 4;}auto req=rt.request();x.n=y.n=0;auto at=uint32_t(c->getPC());if(at==0xc6e)++timeouts;if(req.service!=kstation::ControllerMidiSysExRuntime::Service::None){using S=kstation::ControllerMidiSysExRuntime::Service;auto target=req.service==S::DspWrite?0x165e:req.service==S::RefreshPanel?0x571e:req.service==S::InitializeVoice?0x816c:req.service==S::ReleaseSound?0x7644:req.service==S::DisplayString?0x239e:req.service==S::DisplayCharacter?0x237e:req.service==S::DisplayNumber?0x12b6:req.service==S::FlashNotice?0x20e2:req.service==S::CommitGlobal?0x4dc0:req.service==S::LoadGlobal?0x5556:req.service==S::Command40?0x3256:req.service==S::Command43?0x3306:req.service==S::Command41?0x332c:0x334a;if(at!=target){std::fprintf(stderr,"request pc=%x target=%x service=%u\n",at,target,unsigned(req.service));return 5;}c->step();d->cycles+=7;d->lastRead=-1;if(!rt.completeService(req.service))return 6;++services;}else{auto budget=rt.nextClocks(*d,irq);if(!budget){std::fprintf(stderr,"cost pc=%x mode=%u type=%u\n",at,mode,type);return 7;}auto before=d->cycles;for(unsigned b=0;b<budget;++b){auto r=rt.advanceBefore(*d,irq,b);if(r.clocks||d->cycles!=before||y.n)return 8;++shorts;}c->step();auto r=rt.advanceBefore(*d,irq,budget);if(!r.clocks)return 9;}if(((c->ccr&128)!=0)!=(irq.mask()==kstation::ControllerInterruptRuntime::Mask::Disabled)){std::fprintf(stderr,"mask pc=%x flags=%x\n",at,flags);return 22;}if(c->cycles!=d->cycles||x.n!=y.n){std::fprintf(stderr,"phase pc=%x mode=%u type=%u count=%u clocks=%llu/%llu io=%u/%u\n",at,mode,type,count,c->cycles,d->cycles,x.n,y.n);return 10;}for(unsigned i=0;i<x.n;++i)if(x.e[i].time!=y.e[i].time||x.e[i].addr!=y.e[i].addr||x.e[i].value!=y.e[i].value||x.e[i].write!=y.e[i].write){std::fprintf(stderr,"event pc=%x addr=%x/%x val=%x/%x time=%llu/%llu\n",at,x.e[i].addr,y.e[i].addr,x.e[i].value,y.e[i].value,x.e[i].time,y.e[i].time);return 11;}events+=x.n;++phases;}if(c->getPC()!=0x7000){std::fprintf(stderr,"early pc=%x mode=%u type=%u flags=%u count=%u\n",c->getPC(),mode,type,flags,count);return 12;}for(uint32_t a=0xba00;a<0xd000;++a)if(c->memory[a]!=d->memory[a]){std::fprintf(stderr,"RAM %x\n",a);return 13;}++graphs;}for(unsigned flags:{0u,128u}){rt.reset();irq.reset();irq.setMask(flags&128?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled);c->pc=c->makepc(0x2f6c);c->setSP(0xffff10);for(unsigned i=0;i<4;++i)c->memory[0xffff10+i]=uint8_t(0x7000u>>(8*(3-i)));c->ccr=uint8_t(flags);c->cycles=d->cycles=250000;c->history(-1,-1);d->lastRead=d->lastWrite=-1;if(!rt.start(kstation::ControllerMidiSysExRuntime::Kind::End,0xcad3))return 16;while(rt.active()){auto cost=rt.nextClocks(*d,irq);if(!cost)return 17;c->step();auto r=rt.advanceBefore(*d,irq,cost);if(!r.clocks||c->cycles!=d->cycles)return 18;++phases;}if(c->getPC()!=0x7000)return 19;++graphs;}if(timeouts!=2||!x.flash.writes||x.flash.writes!=y.flash.writes||std::memcmp(c->memory+0x200000,d->memory+0x200000,0x40000))return 21;std::printf("{\"passed\":true,\"graphs\":%llu,\"phases\":%llu,\"events\":%llu,\"short_budgets\":%llu,\"external_services\":%llu,\"flash_writes\":%u,\"timeouts\":%llu}\n",(unsigned long long)graphs,(unsigned long long)phases,(unsigned long long)events,(unsigned long long)shorts,(unsigned long long)services,x.flash.writes,(unsigned long long)timeouts);}
